import{_ as r,o as a,c as t,a5 as o}from"./chunks/framework.CXvGqWf0.js";const u=JSON.parse('{"title":"漫画 · 第 34 话 Observer 三件套：浏览器原生推送替代轮询","description":"","frontmatter":{},"headers":[],"relativePath":"comics/html/EP.34-observers.md","filePath":"comics/html/EP.34-observers.md","lastUpdated":1793421609000}'),s={name:"comics/html/EP.34-observers.md"};function l(i,e,n,c,h,d){return a(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="漫画-·-第-34-话-observer-三件套-浏览器原生推送替代轮询" tabindex="-1">漫画 · 第 34 话 Observer 三件套：浏览器原生推送替代轮询 <a class="header-anchor" href="#漫画-·-第-34-话-observer-三件套-浏览器原生推送替代轮询" aria-label="Permalink to &quot;漫画 · 第 34 话 Observer 三件套：浏览器原生推送替代轮询&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../../docs/html/11-observers">docs/html/11-observers.md</a> ｜ 原画：<a href="./EP.34-observers.svg">EP.34-observers.svg</a></p></blockquote><h2 id="登场角色" tabindex="-1">登场角色 <a class="header-anchor" href="#登场角色" aria-label="Permalink to &quot;登场角色&quot;">​</a></h2><ul><li><strong>像素酱</strong>：CSS 造型师，本话主角。懒加载写 scroll 监听 + 节流、卡片宽度写 window.resize、DOM 变化写 setInterval 轮询，三个定时器同时耗电。</li><li><strong>标签君</strong>：HTML5 结构师，搬出 IntersectionObserver、ResizeObserver、MutationObserver 三件套，浏览器原生推送替代一切轮询。</li></ul><h2 id="剧情梗概" tabindex="-1">剧情梗概 <a class="header-anchor" href="#剧情梗概" aria-label="Permalink to &quot;剧情梗概&quot;">​</a></h2><p>像素酱被「监听元素状态」折磨：scroll 事件高频触发、getBoundingClientRect 强制布局、setInterval 轮询 DOM 变化。标签君引入三大 Observer —— 浏览器在布局后批量回调，推送而非轮询。像素酱发现懒加载、无限滚动、响应式卡片、DOM 变化日志，全部可以零 scroll 监听完成。</p><h2 id="分格解读" tabindex="-1">分格解读 <a class="header-anchor" href="#分格解读" aria-label="Permalink to &quot;分格解读&quot;">​</a></h2><h3 id="格1-·-痛点现场" tabindex="-1">格1 · 痛点现场 <a class="header-anchor" href="#格1-·-痛点现场" aria-label="Permalink to &quot;格1 · 痛点现场&quot;">​</a></h3><p>传统方案全是轮询：scroll 监听 + 节流 + getBoundingClientRect 做懒加载；window.resize 监听卡片宽度；setInterval 轮询 DOM 变化。三个定时器同时耗电，组件卸载忘清理就内存泄漏，SSR 环境直接报错。</p><h3 id="格2-·-机制登场" tabindex="-1">格2 · 机制登场 <a class="header-anchor" href="#格2-·-机制登场" aria-label="Permalink to &quot;格2 · 机制登场&quot;">​</a></h3><p>三大 Observer 推送式 API：<code>IntersectionObserver</code> 监听元素与视口交叉（合成器级计算，主线程零负担）；<code>ResizeObserver</code> 监听元素尺寸变化（布局后触发，不强制 reflow）；<code>MutationObserver</code> 监听 DOM 增删改（批量回调，天然防抖）。</p><h3 id="格3-·-落地收束" tabindex="-1">格3 · 落地收束 <a class="header-anchor" href="#格3-·-落地收束" aria-label="Permalink to &quot;格3 · 落地收束&quot;">​</a></h3><p>四大场景：图片懒加载提前 200px、无限滚动哨兵模式、响应式卡片与 window.resize 解耦、DOM 变化日志实时推送。记住铁律：<strong>用完即 disconnect</strong>——Observer 持续持有引用，不清理就是内存泄漏。</p><h2 id="码叔划重点" tabindex="-1">码叔划重点 <a class="header-anchor" href="#码叔划重点" aria-label="Permalink to &quot;码叔划重点&quot;">​</a></h2><ol><li>Observer 是推送而非轮询：浏览器布局后批量回调，自带节流，不阻塞主线程。</li><li>用完即 disconnect：组件卸载时不清理，Observer 持续持有引用导致内存泄漏。</li><li>ResizeObserver 回调里改尺寸会触发循环警告，用 requestAnimationFrame 延迟到下一帧。</li></ol><h2 id="自测一题" tabindex="-1">自测一题 <a class="header-anchor" href="#自测一题" aria-label="Permalink to &quot;自测一题&quot;">​</a></h2><p><strong>问</strong>：为什么 IntersectionObserver 比 scroll 监听 + getBoundingClientRect 性能好？</p><p><strong>答</strong>：scroll 监听在主线程高频触发，每次都要同步调用 <code>getBoundingClientRect()</code> 强制布局；IntersectionObserver 的交叉计算在合成器线程完成，主线程只收批量回调结果，且自带节流，不阻塞渲染。</p><h2 id="动手实验" tabindex="-1">动手实验 <a class="header-anchor" href="#动手实验" aria-label="Permalink to &quot;动手实验&quot;">​</a></h2><ul><li>图片懒加载 + 无限滚动 + 吸顶导航 + 响应式卡片 + DOM 变化日志：<a href="./../../examples/html/11-observers/index-01-observers.html">examples/html/11-observers/</a></li></ul><h2 id="下一话预告" tabindex="-1">下一话预告 <a class="header-anchor" href="#下一话预告" aria-label="Permalink to &quot;下一话预告&quot;">​</a></h2><p>第 35 话《……》—— 批次 6 待续，更多 CSS/HTML 高级特性正在路上。</p>',22)])])}const v=r(s,[["render",l]]);export{u as __pageData,v as default};
